define(["jquery"],function($){var parse=function(value){return String(value||"").split(/\r?\n/).map(function(line){var parts=line.split("|").map(function(part){return part.trim()});if(!parts[0]||!parts[1]){return null}return{time:parts[0],label:parts[1],skip:(parts[2]||"").toLowerCase()==="skip"}}).filter(Boolean)};var init=function(fieldName){var $textarea=$("#id_"+fieldName);if(!$textarea.length||$textarea.data("markers-builder")){return}$textarea.data("markers-builder",true).addClass("d-none").attr("aria-hidden","true");var $builder=$("<div>",{class:"supervideo-markers-builder border rounded p-3"});var $rows=$("<div>",{class:"supervideo-markers-rows"});var $add=$("<button>",{type:"button",class:"btn btn-secondary mt-2",text:M.util.get_string("markers_add","supervideo")});$builder.append($rows,$add);$textarea.after($builder);var serialize=function(){var lines=[];$rows.find(".supervideo-marker-row").each(function(){var $row=$(this);var time=$row.find("[data-marker-time]").val().trim();var label=$row.find("[data-marker-label]").val().trim();if(!time&&!label){return}lines.push(time+" | "+label+($row.find("[data-marker-skip]").is(":checked")?" | skip":""))});$textarea.val(lines.join("\n")).trigger("change")};var addRow=function(marker){marker=marker||{time:"",label:"",skip:false};var $row=$("<div>",{class:"supervideo-marker-row row g-2 align-items-end mb-2"});var $timeCol=$("<div>",{class:"col-12 col-md-3"});var $labelCol=$("<div>",{class:"col-12 col-md-5"});var $removeCol=$("<div>",{class:"col-4 col-md-2 text-end"});var $skipCol=$("<div>",{class:"col-12"});var $timeLabel=$("<label>",{class:"form-label",text:M.util.get_string("markers_time","supervideo")});var $time=$("<input>",{type:"text",class:"form-control",value:marker.time,placeholder:"00:30","data-marker-time":"1",style:"width: auto; max-width: stretch;"});var $labelLabel=$("<label>",{class:"form-label",text:M.util.get_string("markers_label","supervideo")});var $label=$("<input>",{type:"text",class:"form-control",value:marker.label,"data-marker-label":"1",style:"width: 100%;"});var checkboxId="supervideo-marker-skip-"+Math.random().toString(36).slice(2);var $checkWrap=$("<div>",{class:"form-check mb-2"});var $skip=$("<input>",{type:"checkbox",class:"form-check-input",id:checkboxId,"data-marker-skip":"1"}).prop("checked",!!marker.skip);var $skipLabel=$("<label>",{class:"form-check-label",for:checkboxId,text:M.util.get_string("markers_skip","supervideo")});var $remove=$("<button>",{type:"button",class:"btn btn-outline-danger",text:M.util.get_string("markers_remove","supervideo")});$timeCol.append($timeLabel,$time);$labelCol.append($labelLabel,$label);$checkWrap.append($skip,$skipLabel);$removeCol.append($remove);$skipCol.append($checkWrap);$row.append($timeCol,$labelCol,$removeCol,$skipCol);$rows.append($row);$row.on("input change","input",serialize);$remove.on("click",function(){$row.remove();serialize()})};parse($textarea.val()).forEach(addRow);if(!$rows.children().length){addRow()}$add.on("click",function(){addRow()})};return{init:init}});